<?php

declare(strict_types=1);

namespace Database\Seeders\Benchmark;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use RuntimeException;

/**
 * Loads the shared benchmark data set (benchmarks/data/*.csv, generated by
 * benchmarks/data/generate.php) into the benchmark tables. Idempotent: truncates first.
 *
 *     php artisan db:seed --class="Database\Seeders\Benchmark\BenchmarkSeeder"
 */
class BenchmarkSeeder extends Seeder
{
    public function run(): void
    {
        $dir = realpath(base_path('../../benchmarks/data')) ?: base_path('../../benchmarks/data');

        DB::table('benchmark_records')->delete();
        DB::table('benchmark_regions')->delete();
        DB::table('benchmark_vendors')->delete();

        $this->load("{$dir}/benchmark_vendors.csv", 'benchmark_vendors');
        $this->load("{$dir}/benchmark_regions.csv", 'benchmark_regions');
        $this->load("{$dir}/benchmark_records.csv", 'benchmark_records');
    }

    protected function load(string $file, string $table): void
    {
        $handle = fopen($file, 'r');

        if ($handle === false) {
            throw new RuntimeException("Cannot read {$file}; run `php benchmarks/data/generate.php` first.");
        }

        /** @var array<int, string> $headers */
        $headers = fgetcsv($handle, escape: '');
        $now = now()->toDateTimeString();
        $rows = [];

        while (($line = fgetcsv($handle, escape: '')) !== false) {
            $row = array_combine($headers, $line);

            foreach ($row as $key => $value) {
                if ($value === '') {
                    $row[$key] = null;
                }
            }

            $row['created_at'] ??= $now;
            $row['updated_at'] ??= $now;
            $rows[] = $row;

            if (count($rows) === 500) {
                DB::table($table)->insert($rows);
                $rows = [];
            }
        }

        if ($rows !== []) {
            DB::table($table)->insert($rows);
        }

        fclose($handle);
    }
}
